const primaryTabs: { id: Tab; label: string; mobileLabel?: string }[] = [
  { id: "overview", label: "單字總覽", mobileLabel: "總覽" },
  { id: "catalog", label: "探索", mobileLabel: "探索" },
  { id: "lookup", label: "查單字", mobileLabel: "查詢" },
  { id: "review", label: "複習與測驗", mobileLabel: "複習" },
  { id: "decks", label: "單字本" },
];
const moreTabs: { id: Tab; label: string; note?: string }[] = [
  { id: "decks", label: "單字本" }, { id: "assistant", label: "AI 學習" }, { id: "stats", label: "學習統計" }, { id: "transfer", label: "匯入／匯出" }, { id: "settings", label: "設定" }, { id: "trash", label: "垃圾桶" },
];

export function VocabularyWorkspace({ initialData }: { initialData?: VocabularyWorkspaceData }) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const [data, setData] = useState(initialData ?? emptyVocabulary);
  const [loaded, setLoaded] = useState(Boolean(initialData));
  const [dataMode, setDataMode] = useState<"active" | "trash">("active");
  const [listLoading, setListLoading] = useState(false);
  const [tab, setTab] = useState<Tab>("overview");
  const [query, setQuery] = useState("");
  const [language, setLanguage] = useState("all");
  const [masteryFilter, setMasteryFilter] = useState<number | null>(null);
  const [kanaFilter, setKanaFilter] = useState<string | null>(null);
  const [deckFilter, setDeckFilter] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [draft, setDraft] = useState<Draft | null>(null);
  const [selected, setSelected] = useState<VocabularyCard | null>(null);
  const [deleting, setDeleting] = useState<VocabularyCard | null>(null);
  const [chosen, setChosen] = useState(new Set<string>());
  const [selectionMode, setSelectionMode] = useState(false);
  const [moreOpen, setMoreOpen] = useState(false);
  const [filterOpen, setFilterOpen] = useState(false);
  const [organizeOpen, setOrganizeOpen] = useState(false);
  const [batchDeckId, setBatchDeckId] = useState<string | null | undefined>(undefined);
  const [batchTagIds, setBatchTagIds] = useState(new Set<string>());
  const [tagName, setTagName] = useState("");
  const [deckName, setDeckName] = useState("");
  const [studySetupMode, setStudySetupMode] = useState<StudyMode | null>(null);
  const [studyCount, setStudyCount] = useState(5);
  const [studyTimerMode, setStudyTimerMode] = useState<StudyTimerMode>("none");
  const [studyCountdownMinutes, setStudyCountdownMinutes] = useState(10);
  const [studyOrder, setStudyOrder] = useState<StudyOrder>("sequential");
  const [studyDirection, setStudyDirection] = useState<"native" | "reverse">("native");
  const [studySession, setStudySession] = useState<StudySession | null>(null);
  const trash = tab === "trash";

  useEffect(() => { const node = document.createElement("style"); node.dataset.vocabularyStyles = "true"; node.textContent = `${vocabularyCss}${vocabularyButtonCss}${vocabularyDashboardCss}${vocabularyMobileSelectionCss}${vocabularyCatalogCss}${vocabularyExamplesCss}${vocabularyDensityCss}${vocabularyCatalogCompactMobileCss}${vocabularyStudyModeCss}${vocabularyMasteryCss}${vocabularyCompactFilterCss}${vocabularyMobileDialogCss}`; document.head.appendChild(node); return () => node.remove(); }, []);
  useEffect(() => {
    let active = true;
    const cached = readClientResource<VocabularyWorkspaceData>("vocabulary:standard");
    if (cached) { setData(cached); setLoaded(true); }
    void fetch("/api/vocabulary", { cache: "no-store" }).then(async (response) => {
      if (!response.ok) throw new Error("單字資料暫時無法讀取。");
      return response.json() as Promise<VocabularyWorkspaceData>;
    }).then((next) => { if (active) { setData(next); setLoaded(true); writeClientResource("vocabulary:standard", next); } }).catch((cause) => { if (active && !cached) setError(cause instanceof Error ? cause.message : "單字資料暫時無法讀取。"); });
    return () => { active = false; };
  }, []);
  useEffect(() => { if (loaded && dataMode === "active") writeClientResource("vocabulary:standard", data); }, [data, loaded, dataMode]);
  useEffect(() => { if (searchParams.get("new") === "1") { setDraft((current) => current ?? blankDraft()); router.replace("/vocabulary", { scroll: false }); } }, [router, searchParams]);
  useEffect(() => {
    const openDraft = () => setDraft((current) => current ?? blankDraft());
    const openFromMobileCreate = (event: MouseEvent) => {
      const target = event.target instanceof Element ? event.target.closest('a[href="/vocabulary?new=1"]') : null;
      if (target) openDraft();
    };
    window.addEventListener("personal-vault:new-vocabulary", openDraft);
    document.addEventListener("click", openFromMobileCreate, true);
    return () => { window.removeEventListener("personal-vault:new-vocabulary", openDraft); document.removeEventListener("click", openFromMobileCreate, true); };
  }, []);
  useEffect(() => { if (!notice) return; const timeout = window.setTimeout(() => setNotice(null), 3200); return () => window.clearTimeout(timeout); }, [notice]);

  const cards = useMemo(() => data.cards.filter((card) => {
    const text = `${card.word} ${card.reading || ""} ${card.primaryTranslation || ""} ${card.notes || ""} ${card.tags.map((tag) => tag.name).join(" ")}`.toLowerCase();
    const kana = toHiragana(card.reading || card.kana || card.word).trim().charAt(0);
    const matchesKana = !kanaFilter || kana === kanaFilter;
    return (language === "all" || card.language === language) && text.includes(query.trim().toLowerCase()) && (tab !== "favorites" || card.isFavorite) && (!deckFilter || card.deckIds.includes(deckFilter)) && (masteryFilter === null || card.currentLevel === masteryFilter) && matchesKana;
  }), [data.cards, deckFilter, kanaFilter, language, masteryFilter, query, tab]);
  const dueCards = useMemo(() => data.cards.filter((card) => card.learningStatus !== "paused" && card.nextReviewAt && new Date(card.nextReviewAt).getTime() <= Date.now()), [data.cards]);
  const quizPreferences = getQuizPreferences(data.settings.flashcardPreferences);
  const studyCards = useMemo(() => data.cards.filter((card) => !card.deletedAt && card.learningStatus !== "paused" && !(card.currentLevel === 5 && !quizPreferences.includeMastered)).sort((a, b) => (a.nextReviewAt ? new Date(a.nextReviewAt).getTime() : Number.MAX_SAFE_INTEGER) - (b.nextReviewAt ? new Date(b.nextReviewAt).getTime() : Number.MAX_SAFE_INTEGER)), [data.cards, quizPreferences.includeMastered]);
  const stat = useMemo(() => { const learningCards = data.cards.filter((card) => !(card.sourceKind === "catalog" && card.learningStatus === "paused")); return { total: learningCards.length, ja: learningCards.filter((card) => card.language === "ja").length, en: learningCards.filter((card) => card.language === "en").length, mastered: learningCards.filter((card) => card.currentLevel >= 5).length, learning: learningCards.filter((card) => card.learningStatus === "learning" || card.learningStatus === "reviewing").length, mastery: masteryLabels.map((_, level) => learningCards.filter((card) => card.currentLevel === level).length), reviewed: data.reviewLogs.filter((log) => day(log.reviewedAt) === day(new Date().toISOString())).length, correct: data.reviewLogs.filter((log) => day(log.reviewedAt) === day(new Date().toISOString()) && log.answerResult).length }; }, [data]);
  const recentCards = useMemo(() => [...data.cards].sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()).slice(0, 3), [data.cards]);
  const streak = useMemo(() => { const days = new Set(data.reviewLogs.map((log) => new Date(log.reviewedAt).toLocaleDateString("sv-SE"))); let count = 0; const cursor = new Date(); while (days.has(cursor.toLocaleDateString("sv-SE"))) { count += 1; cursor.setDate(cursor.getDate() - 1); } return count; }, [data.reviewLogs]);
  const allChosen = cards.length > 0 && cards.every((card) => chosen.has(card.id));

  async function load(withTrash = trash) {
    setListLoading(true);
    setLoaded(false);
    try {
      const response = await fetch(`/api/vocabulary${withTrash ? "?trash=1" : ""}`, { cache: "no-store" });
      if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.error || "單字資料暫時無法讀取。"); }
      const next = await response.json() as VocabularyWorkspaceData;
      setData(next); setLoaded(true); setDataMode(withTrash ? "trash" : "active"); if (!withTrash) writeClientResource("vocabulary:standard", next);
    } finally { setListLoading(false); }
  }
  async function request(url: string, init: RequestInit) {
    setPending(true); setError(null);
    try { const response = await fetch(url, { ...init, headers: { "Content-Type": "application/json", ...(init.headers || {}) } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || "操作失敗"); return body as Record<string, unknown>; }
    catch (cause) { setError(cause instanceof Error ? cause.message : "操作失敗，請稍後再試。"); return null; }
    finally { setPending(false); }
  }
  async function save(event: FormEvent) {
    event.preventDefault(); if (!draft) return;
    let languageDetails: Record<string, unknown> = {};
    try { languageDetails = JSON.parse(draft.languageDetails || "{}"); } catch { setError("語言補充資料必須是有效的 JSON。"); return; }
    const meanings = draft.meaningsText.split("\n").map((value) => value.trim()).filter(Boolean).map((meaning, index) => ({ meaning, language: "zh-TW", isPrimary: index === 0, sortOrder: index }));
    const examples = draft.examplesText.split("\n").map((value) => value.trim()).filter(Boolean).map((value) => { const [sentence, translation] = value.split("｜"); const normalized = translation?.trim() || null; return { sentence: sentence.trim(), translation: normalized, translationZhTw: draft.language === "ja" ? normalized : null }; });
    const result = await request("/api/vocabulary", { method: draft.id ? "PUT" : "POST", body: JSON.stringify({ ...draft, jlptLevel: draft.jlptLevel || null, cefrLevel: draft.cefrLevel || null, languageDetails, meanings, examples }) });
    if (result) {
      const word = draft.word;
      const editing = Boolean(draft.id);
      setDraft(null);
      try {
        await load(false);
        setNotice(editing ? `已儲存「${word}」的修改。` : `已將「${word}」加入單字庫。`);
      } catch (cause) {
        setError(cause instanceof Error ? cause.message : "單字已儲存，但清單重新整理失敗；請稍後再試。");
      }
    }
  }
  async function mutate(ids: string[], action: "trash" | "restore" | "permanent") { const result = await request("/api/vocabulary", { method: "PATCH", body: JSON.stringify({ ids, action }) }); if (result) { setSelected(null); setDeleting(null); setChosen(new Set()); setSelectionMode(false); await load(action === "restore" ? false : trash); setNotice(action === "trash" ? "已移至垃圾桶。" : action === "restore" ? "已還原單字。" : "已永久刪除單字。"); } }
  async function organizeSelected() { if (!chosen.size) return; const result = await request("/api/vocabulary", { method: "PATCH", body: JSON.stringify({ ids: [...chosen], action: "organize", deckId: batchDeckId, tagIds: [...batchTagIds] }) }); if (result) { setOrganizeOpen(false); setBatchDeckId(undefined); setBatchTagIds(new Set()); setChosen(new Set()); setSelectionMode(false); await load(false); } }
  async function saveStudyReviews(reviews: LocalReview[]) {
    if (!reviews.length) { setStudySession(null); return; }
    const result = await request("/api/vocabulary/review", { method: "POST", body: JSON.stringify({ reviews }) });
    if (!result) return;
    await load(false);
    setStudySession(null);
    const outcomes = Array.isArray(result.outcomes) ? result.outcomes as { oldLevel?: number; newLevel?: number }[] : [];
    const changed = outcomes.filter((item) => item.oldLevel !== item.newLevel).length;
    setNotice(`已一次儲存 ${reviews.length} 筆答題紀錄。${changed ? ` ${changed} 個單字的熟練度已更新。` : ""}`);
  }
  function openStudySetup(mode: StudyMode) {
    setStudySetupMode(mode);
    setStudyCount(Math.min(Math.max(5, Math.min(10, studyCards.length)), Math.max(5, studyCards.length)));
    setStudyTimerMode("none");
    setStudyCountdownMinutes(10);
    setStudyOrder("sequential");
    setStudyDirection("native");
  }
  function orderedStudyCards(order: StudyOrder) {
    const next = [...studyCards];
    if (quizPreferences.mode === "smart") {
      const weighted = selectWeightedCards(next, next.length);
      if (order === "random") return weighted;
      if (order === "sequential") return weighted;
      return weighted.sort((a, b) => (a.jlptLevel || "ZZ").localeCompare(b.jlptLevel || "ZZ"));
    }
    if (order === "random") {
      for (let index = next.length - 1; index > 0; index -= 1) { const target = Math.floor(Math.random() * (index + 1)); [next[index], next[target]] = [next[target], next[index]]; }
      return next;
    }
    if (order === "jlpt") {
      const levels: Record<string, number> = { N5: 0, N4: 1, N3: 2, N2: 3, N1: 4 };
      return next.sort((a, b) => (levels[a.jlptLevel || ""] ?? 99) - (levels[b.jlptLevel || ""] ?? 99));
    }
    return next;
  }
  function startStudySession() {
    if (!studySetupMode || studyCards.length < 5) return;
    const count = Math.min(Math.max(5, studyCount), studyCards.length);
    setStudySession({ mode: studySetupMode, cards: orderedStudyCards(studyOrder).slice(0, count), timerMode: studyTimerMode, countdownMinutes: studyCountdownMinutes, direction: studyDirection });
    setStudySetupMode(null);
  }
  async function createTaxonomy(type: "tag" | "deck") { const name = type === "tag" ? tagName : deckName; if (!name.trim()) return; const result = await request("/api/vocabulary/taxonomy", { method: "POST", body: JSON.stringify(type === "tag" ? { type, name, color: "#2f67c7" } : { type, name }) }); if (result) { type === "tag" ? setTagName("") : setDeckName(""); await load(false); } }
  async function saveSettings(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const flashcardPreferences = { ...data.settings.flashcardPreferences, quizMode: form.get("quizMode") === "equal" ? "equal" : "smart", includeMasteredInQuiz: form.get("includeMasteredInQuiz") === "on" }; const result = await request("/api/vocabulary/taxonomy", { method: "POST", body: JSON.stringify({ type: "settings", dailyNewGoal: Number(form.get("dailyNewGoal")), dailyReviewGoal: Number(form.get("dailyReviewGoal")), flashcardPreferences }) }); if (result) { await load(false); setNotice("已儲存測驗設定。"); } }
  function setField(key: keyof Draft, value: Draft[keyof Draft]) { setDraft((current) => current ? { ...current, [key]: value } : current); }
  function activateTab(next: Tab, preserveFilters = false) { setTab(next); setChosen(new Set()); setSelectionMode(false); if (!preserveFilters) { setQuery(""); setDeckFilter(null); setMasteryFilter(null); setKanaFilter(null); } setMoreOpen(false); if (next === "trash") void load(true).catch((cause) => setError(cause instanceof Error ? cause.message : "垃圾桶資料暫時無法讀取。")); else if (dataMode === "trash") void load(false).catch((cause) => setError(cause instanceof Error ? cause.message : "單字資料暫時無法讀取。")); }
  function toggleChoice(id: string) { setChosen((current) => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; }); }
  function toggleBatchTag(id: string) { setBatchTagIds((current) => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; }); }
  async function toggleFavorite(card: VocabularyCard) { const result = await request("/api/vocabulary", { method: "PUT", body: JSON.stringify({ ...fromCard(card), isFavorite: !card.isFavorite, meanings: card.meanings, examples: card.examples, languageDetails: card.languageDetails }) }); if (result) await load(false); }
  const isListTab = ["overview", "favorites", "trash"].includes(tab);
  const selectedCount = chosen.size;
  const actionWord = trash ? "永久刪除" : "移至垃圾桶";
  const viewReady = loaded && !listLoading && (trash ? dataMode === "trash" : dataMode === "active");

  return <section className="vocabulary-workspace">
    {pending && <OperationStatus label="正在更新單字資料…" />}
    {error && <p className="notice error" role="alert">{error}</p>}
    {notice && <p className="notice success" role="status">{notice}</p>}
    <header className="vocabulary-header"><div><p className="eyebrow">VOCABULARY LEARNING</p><h1>單字學習</h1><p>記錄、整理與間隔複習你的日文、英文及更多語言。</p></div><button className="button vocabulary-primary-action" onClick={() => setDraft(blankDraft())} type="button">＋ 新增單字</button></header>
    <nav aria-label="單字學習功能" className="vocabulary-tabs">{tabs.map((item) => { const isPrimary = primaryTabs.some((primary) => primary.id === item.id); const mobileItem = primaryTabs.find((primary) => primary.id === item.id); return <button className={`${tab === item.id ? "active" : ""} ${item.id === "decks" ? "vocabulary-decks-tab" : ""} ${isPrimary ? "" : "vocabulary-tab-overflow"}`} key={item.id} onClick={() => activateTab(item.id)} type="button"><span className="vocabulary-tab-wide">{item.label}</span><span className="vocabulary-mobile-only">{mobileItem?.mobileLabel || item.label}</span>{item.id === "review" && dueCards.length > 0 ? <b>{dueCards.length}</b> : null}</button>; })}<button aria-expanded={moreOpen} className={`vocabulary-tab-more ${moreTabs.some((item) => item.id === tab) ? "active" : ""} ${tab === "decks" ? "deck-active" : ""}`} onClick={() => setMoreOpen(true)} type="button">更多</button></nav>

    {tab === "catalog" && <VocabularyCatalog onChanged={() => load(false)} />}
    {tab === "lookup" && <VocabularyLookupPanel cards={data.cards} mode="lookup" onAdd={(entry) => setDraft({ ...blankDraft(), ...entry })} />}
    {tab === "assistant" && <VocabularyLookupPanel cards={data.cards} mode="assistant" onAdd={(entry) => setDraft({ ...blankDraft(), ...entry })} />}
    {tab === "review" && (studySession ? <section className="vocabulary-study-session"><div className="vocabulary-study-session-toolbar"><div><p className="eyebrow">{studySession.mode === "review" ? "REVIEW SESSION" : "QUIZ SESSION"}</p><h2>{studySession.mode === "review" ? "本次複習" : "本次測驗"} · {studySession.cards.length} 個單字</h2></div><button className="secondary-button compact" onClick={() => setStudySession(null)} type="button">放棄本次</button></div><StudySessionTimer countdownMinutes={studySession.countdownMinutes} mode={studySession.timerMode} onElapsed={() => { setNotice("時間到，本次練習已結束，尚未儲存的結果不會寫入。"); setStudySession(null); }} />{studySession.mode === "review" ? <FlashcardReview cards={studySession.cards} direction={studySession.direction} onComplete={saveStudyReviews} pending={pending} /> : <VocabularyQuizSession cards={studySession.cards} onComplete={saveStudyReviews} />}</section> : <StudyModeHome availableCount={studyCards.length} dueCount={dueCards.length} onChoose={openStudySetup} />)}
    {tab === "decks" && <section className="vocabulary-taxonomy"><div><p className="eyebrow">WORD BOOKS</p><h2>單字本</h2><form onSubmit={(event) => { event.preventDefault(); void createTaxonomy("deck"); }}><input onChange={(event) => setDeckName(event.target.value)} placeholder="例如：JLPT N3、程式英文" value={deckName} /><button className="button" type="submit">新增單字本</button></form><div className="vocabulary-chip-list">{data.decks.map((deck) => <button key={deck.id} onClick={() => { setDeckFilter(deck.id); activateTab("overview", true); }} type="button"><strong>{deck.name}</strong><span>{deck.cardIds.length} 個單字</span></button>)}{!data.decks.length && <p>還沒有單字本。</p>}</div></div><div><p className="eyebrow">TAGS</p><h2>標籤</h2><form onSubmit={(event) => { event.preventDefault(); void createTaxonomy("tag"); }}><input onChange={(event) => setTagName(event.target.value)} placeholder="例如：動漫、TOEIC" value={tagName} /><button className="button" type="submit">新增標籤</button></form><div className="vocabulary-tag-list">{data.tags.map((tag) => <span key={tag.id} style={{ borderColor: tag.color || undefined }}>{tag.name}</span>)}{!data.tags.length && <p>還沒有標籤。</p>}</div></div></section>}
    {tab === "stats" && <section className="vocabulary-stats"><div className="vocabulary-stat-grid">{[["總單字", stat.total], ["日文", stat.ja], ["英文", stat.en], ["今日複習", stat.reviewed], ["今日答對", stat.correct], ["已掌握", stat.mastered]].map(([label, value]) => <div key={String(label)}><strong>{value}</strong><span>{label}</span></div>)}</div><section className="vocabulary-chart"><h2>熟練度分布</h2>{[0, 1, 2, 3, 4, 5].map((level) => { const count = data.cards.filter((card) => card.currentLevel === level).length; return <div key={level}><span>{masteryLabels[level]}</span><i style={{ width: `${stat.total ? (count / stat.total) * 100 : 0}%` }} /><b>{count}</b></div>; })}</section></section>}
    {tab === "transfer" && <Transfer request={request} load={load} />}
    {tab === "settings" && <form className="vocabulary-settings" onSubmit={saveSettings}><h2>學習設定</h2><label>每日新增目標<input defaultValue={data.settings.dailyNewGoal} min="0" name="dailyNewGoal" type="number" /></label><label>每日複習目標<input defaultValue={data.settings.dailyReviewGoal} min="1" name="dailyReviewGoal" type="number" /></label><fieldset className="vocabulary-quiz-settings"><legend>測驗出題模式</legend><label className="vocabulary-choice-row"><input defaultChecked={quizPreferences.mode === "smart"} name="quizMode" type="radio" value="smart" /><span><strong>智慧熟練度模式</strong><small>依答題紀錄、近期表現與距離上次答題時間調整出題機率。</small></span></label><label className="vocabulary-choice-row"><input defaultChecked={quizPreferences.mode === "equal"} name="quizMode" type="radio" value="equal" /><span><strong>所有單字等機率</strong><small>忽略熟練度，所有符合條件的單字有相同機率。</small></span></label></fieldset><fieldset className="vocabulary-quiz-settings"><legend>完全掌握單字</legend><label className="vocabulary-choice-row"><input defaultChecked={quizPreferences.includeMastered} name="includeMasteredInQuiz" type="checkbox" /><span><strong>完全掌握的單字仍然參加測驗</strong><small>開啟後仍會低機率出現；關閉後不會納入一般練習。</small></span></label></fieldset><button className="button" disabled={pending} type="submit">儲存設定</button></form>}

    {isListTab && <section className="vocabulary-dashboard"><div className="vocabulary-main-column"><div className="vocabulary-summary vocabulary-mastery-summary">{masteryLabels.map((label, level) => <button className={level === 0 ? "vocabulary-due-card" : ""} key={label} onClick={() => { setMasteryFilter(level); setFilterOpen(true); }} type="button"><strong>{stat.mastery[level]}</strong><span>{label}</span>{level === 0 && <em>開始學習 →</em>}</button>)}</div><LearningPanels className="vocabulary-mobile-learning-panel" data={data} recentCards={recentCards} reviewed={stat.reviewed} streak={streak} onOpenCard={setSelected} /><div className="vocabulary-list-toolbar"><div className="vocabulary-filters"><input id="vocabulary-search" aria-label="搜尋單字" onChange={(event) => setQuery(event.target.value)} placeholder="搜尋單字、讀音或意思" value={query} /><button className="vocabulary-filter-button" onClick={() => setFilterOpen(true)} type="button">{language === "all" ? "所有語言" : language === "ja" ? "日文" : "英文"} · 篩選</button><button className="vocabulary-selection-button" onClick={() => { setSelectionMode((value) => !value); setChosen(new Set()); }} type="button">{selectionMode ? "結束選取" : "選取"}</button></div>{selectionMode && <div className="vocabulary-selection-toolbar"><strong>已選取 {selectedCount} 筆</strong><button className="secondary-button compact" onClick={() => setChosen(allChosen ? new Set() : new Set(cards.map((card) => card.id)))} type="button">{allChosen ? "取消全選" : "全選"}</button><button className="secondary-button compact" onClick={() => { setSelectionMode(false); setChosen(new Set()); }} type="button">取消</button>{selectedCount > 0 && <><button className="secondary-button compact" onClick={() => setOrganizeOpen(true)} type="button">整理</button><button className="delete-button compact" onClick={() => setDeleting(cards.find((card) => chosen.has(card.id)) || null)} type="button">{actionWord}</button></>}</div>}</div><div className="vocabulary-card-list">{!loaded ? <VocabularyListSkeleton /> : cards.map((card) => <VocabularyCardRow card={card} key={card.id} onFavorite={() => void toggleFavorite(card)} onOpen={() => setSelected(card)} onToggle={() => toggleChoice(card.id)} selected={chosen.has(card.id)} selectionMode={selectionMode} />)}{loaded && !cards.length && <div className="vocabulary-empty"><strong>{trash ? "垃圾桶是空的" : "找不到符合的單字"}</strong><p>{trash ? "被刪除的單字會保留在這裡，可於之後還原。" : "試著調整篩選條件，或先從字典查詢並加入第一筆單字。"}</p>{!trash && <button className="secondary-button compact" onClick={() => activateTab("lookup")} type="button">查字典</button>}</div>}</div></div><LearningPanels className="vocabulary-side-panel" data={data} recentCards={recentCards} reviewed={stat.reviewed} streak={streak} onOpenCard={setSelected} /></section>}

    <ModalDialog className="vocabulary-more-dialog" onClose={() => setMoreOpen(false)} open={moreOpen} title="更多功能"> <div className="vocabulary-more-list">{moreTabs.map((item) => <button key={item.id} onClick={() => activateTab(item.id)} type="button"><span>{item.label}</span>{item.id === "trash" ? <small>已刪除資料</small> : null}</button>)}</div></ModalDialog>
    <ModalDialog className="vocabulary-more-dialog" onClose={() => setFilterOpen(false)} open={filterOpen} title="篩選單字"><div className="vocabulary-filter-list"><section className="vocabulary-filter-section"><h3>語言</h3><div className="vocabulary-filter-chips">{[["all", "所有語言"], ["ja", "日文"], ["en", "英文"]].map(([value, label]) => <button className={language === value ? "active" : ""} key={value} onClick={() => setLanguage(value)} type="button">{label}</button>)}</div></section><section className="vocabulary-filter-section"><h3>熟練度</h3><div className="vocabulary-filter-chips"><button className={masteryFilter === null ? "active" : ""} onClick={() => setMasteryFilter(null)} type="button">全部</button>{masteryLabels.map((label, level) => <button className={masteryFilter === level ? "active" : ""} key={label} onClick={() => setMasteryFilter(level)} type="button">{label}</button>)}</div></section><section className="vocabulary-filter-section"><h3>五十音</h3><div className="vocabulary-filter-chips vocabulary-kana-filter-chips"><button className={!kanaFilter ? "active" : ""} onClick={() => setKanaFilter(null)} type="button">全部</button>{kanaFilters.map((kana) => <button className={kanaFilter === kana ? "active" : ""} key={kana} onClick={() => setKanaFilter(kana)} type="button">{kana}</button>)}</div></section><section className="vocabulary-filter-section"><h3>單字本</h3><p>選擇一本單字本以縮小清單範圍。</p><div className="vocabulary-filter-chips"><button className={!deckFilter ? "active" : ""} onClick={() => setDeckFilter(null)} type="button">全部單字本</button>{data.decks.map((deck) => <button className={deckFilter === deck.id ? "active" : ""} key={deck.id} onClick={() => setDeckFilter(deck.id)} type="button">{deck.name}</button>)}</div></section><div className="dialog-actions"><button className="secondary-button" onClick={() => { setLanguage("all"); setDeckFilter(null); setMasteryFilter(null); setKanaFilter(null); }} type="button">重設</button><button className="button" onClick={() => setFilterOpen(false)} type="button">套用篩選</button></div></div></ModalDialog>
    <ModalDialog className="vocabulary-study-setup-dialog" onClose={() => setStudySetupMode(null)} open={Boolean(studySetupMode)} title={studySetupMode === "review" ? "設定複習模式" : "設定測驗模式"}>{studySetupMode && <form className="vocabulary-study-setup" onSubmit={(event) => { event.preventDefault(); startStudySession(); }}><p>本次會從 {studyCards.length} 個符合設定的單字中建立練習清單。</p>{studyCards.length < 5 ? <p className="notice error">目前只有 {studyCards.length} 個可練習的單字；至少需要 5 個才能開始。</p> : <><label>本次單字數<input max={studyCards.length} min="5" onChange={(event) => setStudyCount(Math.min(studyCards.length, Math.max(5, Number(event.target.value) || 5)))} type="number" value={studyCount} /><small>最少 5 個，最多 {studyCards.length} 個。</small></label>{studySetupMode === "review" && <fieldset><legend>顯示方向</legend><div className="vocabulary-filter-chips"><button className={studyDirection === "native" ? "active" : ""} onClick={() => setStudyDirection("native")} type="button">日文 → 中文</button><button className={studyDirection === "reverse" ? "active" : ""} onClick={() => setStudyDirection("reverse")} type="button">中文 → 日文</button></div></fieldset>}<fieldset><legend>計時方式</legend><div className="vocabulary-filter-chips">{[["none", "不計時"], ["countup", "開始計時"], ["countdown", "倒數計時"]].map(([value, label]) => <button className={studyTimerMode === value ? "active" : ""} key={value} onClick={() => setStudyTimerMode(value as StudyTimerMode)} type="button">{label}</button>)}</div></fieldset>{studyTimerMode === "countdown" && <label>倒數分鐘<input max="180" min="1" onChange={(event) => setStudyCountdownMinutes(Math.min(180, Math.max(1, Number(event.target.value) || 1)))} type="number" value={studyCountdownMinutes} /></label>}<fieldset><legend>出題順序</legend><div className="vocabulary-filter-chips">{[["sequential", "依複習順序"], ["random", "打亂隨機"], ["jlpt", "依 JLPT N5 → N1"]].map(([value, label]) => <button className={studyOrder === value ? "active" : ""} key={value} onClick={() => setStudyOrder(value as StudyOrder)} type="button">{label}</button>)}</div></fieldset></>}<div className="dialog-actions"><button className="button" disabled={studyCards.length < 5} type="submit">開始{studySetupMode === "review" ? "複習" : "測驗"}</button><button className="secondary-button" onClick={() => setStudySetupMode(null)} type="button">取消</button></div></form>}</ModalDialog>
    <ModalDialog className="vocabulary-more-dialog" onClose={() => setOrganizeOpen(false)} open={organizeOpen} pending={pending} title={`整理 ${selectedCount} 筆單字`}><div className="vocabulary-filter-list"><section className="vocabulary-filter-section"><h3>移至單字本</h3><p>每個單字會保留在一個指定單字本；選擇「不變更」不會改動既有單字本。</p><div className="vocabulary-filter-chips"><button className={batchDeckId === undefined ? "active" : ""} onClick={() => setBatchDeckId(undefined)} type="button">不變更</button><button className={batchDeckId === null ? "active" : ""} onClick={() => setBatchDeckId(null)} type="button">移出單字本</button>{data.decks.map((deck) => <button className={batchDeckId === deck.id ? "active" : ""} key={deck.id} onClick={() => setBatchDeckId(deck.id)} type="button">{deck.name}</button>)}</div></section><section className="vocabulary-filter-section"><h3>加入標籤</h3><p>可複選；只會新增標籤，不會移除既有標籤。</p><div className="vocabulary-filter-chips">{data.tags.map((tag) => <button className={batchTagIds.has(tag.id) ? "active" : ""} key={tag.id} onClick={() => toggleBatchTag(tag.id)} type="button">{batchTagIds.has(tag.id) ? "✓ " : ""}{tag.name}</button>)}{!data.tags.length && <p>尚未建立標籤。</p>}</div></section><div className="dialog-actions"><button className="button" disabled={pending} onClick={() => void organizeSelected()} type="button">套用整理</button><button className="secondary-button" disabled={pending} onClick={() => setOrganizeOpen(false)} type="button">取消</button></div></div></ModalDialog>
    <ModalDialog onClose={() => setDraft(null)} open={Boolean(draft)} pending={pending} title={draft?.id ? "修改單字" : "新增單字"}>{draft && <Editor data={data} draft={draft} pending={pending} setField={setField} onCancel={() => setDraft(null)} onSave={save} />}</ModalDialog>
    <ModalDialog onClose={() => setSelected(null)} open={Boolean(selected)} pending={pending} title={selected?.word || "單字詳細資料"}>{selected && <div className="vocabulary-detail"><p className="eyebrow">{selected.language.toUpperCase()} · {selected.learningStatus}</p><h2>{selected.word}</h2><p>{selected.reading || selected.romaji}</p><h3>{selected.primaryTranslation || selected.meanings.map((meaning) => meaning.meaning).join("、")}</h3><section className="vocabulary-mastery-detail"><h4>{masteryLabels[selected.currentLevel] || masteryLabels[0]}</h4><p>答題次數：{selected.totalAttempts}　答對：{selected.correctCount}　答錯：{selected.wrongCount}</p><p>答對率：{Math.round(selected.correctRate)}%　連續答對：{selected.consecutiveCorrect} 次</p>{selected.lastAnsweredAt && <p>最後答題：{new Date(selected.lastAnsweredAt).toLocaleString("zh-TW")}（{selected.lastAnswerCorrect ? "答對" : "答錯"}）</p>}</section>{selected.meanings.length > 0 && <section><h4>意思</h4>{selected.meanings.map((meaning) => <p key={meaning.id}>{meaning.meaning}{meaning.partOfSpeech ? ` · ${meaning.partOfSpeech}` : ""}</p>)}</section>}{selected.examples.length > 0 && <section><h4>例句</h4>{selected.examples.map((example) => <p key={example.id}><strong>{example.sentence}</strong><br />{example.translation}</p>)}</section>}<p>{selected.notes}</p><div className="dialog-actions">{selected.deletedAt ? <><button className="button" onClick={() => void mutate([selected.id], "restore")} type="button">還原</button><button className="delete-button" onClick={() => setDeleting(selected)} type="button">永久刪除</button></> : <><button className="secondary-button" onClick={() => { setDraft(fromCard(selected)); setSelected(null); }} type="button">修改</button><button className="delete-button" onClick={() => setDeleting(selected)} type="button">移至垃圾桶</button></>}</div></div>}</ModalDialog>
    <ConfirmDialog confirmLabel={trash || deleting?.deletedAt ? "永久刪除" : "移至垃圾桶"} description={trash || deleting?.deletedAt ? `確定要永久刪除 ${chosen.size || 1} 筆單字嗎？此操作無法復原。` : `確定要將 ${chosen.size || 1} 筆單字移至垃圾桶嗎？`} onCancel={() => setDeleting(null)} onConfirm={() => void mutate(chosen.size ? [...chosen] : deleting ? [deleting.id] : [], trash || deleting?.deletedAt ? "permanent" : "trash")} open={Boolean(deleting)} pending={pending} title={trash || deleting?.deletedAt ? "永久刪除單字？" : "移至垃圾桶？"} />
  </section>;
}

function StudyModeHome({ availableCount, dueCount, onChoose }: { availableCount: number; dueCount: number; onChoose: (mode: StudyMode) => void }) {
  return <section className="vocabulary-study-home"><header><p className="eyebrow">STUDY SPACE</p><h2>今天想怎麼練習？</h2><p>先選擇模式，再設定本次單字數、計時與出題順序。</p></header><div className="vocabulary-study-mode-grid"><button className="vocabulary-study-mode-card" onClick={() => onChoose("review")} type="button"><span>◎</span><strong>複習模式</strong><p>翻開單字卡、查看答案，並以答對或答錯讓系統自動安排下一次複習。</p><small>目前 {dueCount} 個待複習</small></button><button className="vocabulary-study-mode-card" onClick={() => onChoose("quiz")} type="button"><span>✦</span><strong>測驗模式</strong><p>依中文提示輸入答案；答題表現會自動更新熟練度。</p><small>{availableCount} 個符合設定的單字可選</small></button></div><p className="vocabulary-study-hint">每次至少選擇 5 個單字；智慧模式會優先抽出答錯較多、近期表現不佳或久未複習的單字。</p></section>;
}

function StudySessionTimer({ mode, countdownMinutes, onElapsed }: { mode: StudyTimerMode; countdownMinutes: number; onElapsed: () => void }) {
  const [elapsed, setElapsed] = useState(0);
  const completed = useRef(false);
  useEffect(() => { setElapsed(0); completed.current = false; }, [mode, countdownMinutes]);
  useEffect(() => {
    if (mode === "none") return;
    const maximum = countdownMinutes * 60;
    const timer = window.setInterval(() => setElapsed((current) => {
      const next = current + 1;
      if (mode === "countdown" && next >= maximum) {
        if (!completed.current) { completed.current = true; window.setTimeout(onElapsed, 0); }
        return maximum;
      }
      return next;
    }), 1000);
    return () => window.clearInterval(timer);
  }, [countdownMinutes, mode, onElapsed]);
  if (mode === "none") return null;
  const total = mode === "countdown" ? Math.max(0, countdownMinutes * 60 - elapsed) : elapsed;
  const minutes = Math.floor(total / 60).toString().padStart(2, "0");
  const seconds = (total % 60).toString().padStart(2, "0");
  return <p className="vocabulary-study-timer" aria-live="polite">{mode === "countdown" ? "剩餘時間" : "已練習"} <strong>{minutes}:{seconds}</strong></p>;
}

function VocabularyQuizSession({ cards, onComplete }: { cards: VocabularyCard[]; onComplete: (reviews: LocalReview[]) => Promise<void> }) {
  const [index, setIndex] = useState(0); const [answer, setAnswer] = useState(""); const [checked, setChecked] = useState<boolean | null>(null); const [skipped, setSkipped] = useState(false); const [results, setResults] = useState<{ card: VocabularyCard; correct: boolean; durationMs: number; occurrenceIndex: number }[]>([]); const [startedAt, setStartedAt] = useState(() => Date.now());
  const card = cards[index];
  const normalize = (value: string) => toHiragana(value).replace(/[\s・ー\-]/g, "").toLocaleLowerCase();
  const expectedAnswers = (item: VocabularyCard) => [item.word, item.reading || "", item.kana || ""].map(normalize).filter(Boolean);
  const next = (correct: boolean) => { if (!card) return; setResults((current) => [...current, { card, correct, durationMs: Date.now() - startedAt, occurrenceIndex: index + 1 }]); setIndex((value) => value + 1); setAnswer(""); setChecked(null); setSkipped(false); setStartedAt(Date.now()); };
  if (!card) { const correctCount = results.filter((item) => item.correct).length; return <section className="vocabulary-quiz vocabulary-quiz-results"><header><p className="eyebrow">QUIZ RESULT</p><h2>測驗結果</h2><p>共 {results.length} 題 · <b className="quiz-correct">答對 {correctCount} 題</b> · <b className="quiz-wrong">答錯 {results.length - correctCount} 題</b> · 正確率 {results.length ? Math.round(correctCount / results.length * 100) : 0}%</p></header><p className="notice">熟練度會依這次的正確率、累計紀錄與近期表現自動更新。</p><div className="vocabulary-quiz-result-list">{results.map((item, resultIndex) => <article className={item.correct ? "correct" : "wrong"} key={`${item.card.id}-${resultIndex}`}><div><strong>{resultIndex + 1}. {item.card.word}</strong><span>{item.card.reading || item.card.kana || ""} · {item.card.primaryTranslation || item.card.meanings[0]?.meaning || ""}</span></div><b>{item.correct ? "答對" : "答錯"}</b></article>)}</div><button className="button" onClick={() => void onComplete(results.map((item) => ({ cardId: item.card.id, answerResult: item.correct, durationMs: item.durationMs, occurrenceIndex: item.occurrenceIndex, mode: "quiz" })))} type="button">儲存本次測驗結果</button></section>; }
  const answerCorrect = checked === true;
  const correctAnswer = `${card.word}${card.reading || card.kana ? `（${card.reading || card.kana}）` : ""}`;
  function submit() { setSkipped(false); setChecked(expectedAnswers(card).includes(normalize(answer))); }
  function skip() { setSkipped(true); setChecked(false); }
  return <section className="vocabulary-quiz"><header><p className="eyebrow">QUIZ</p><span>{index + 1} ／ {cards.length}</span></header><div className="vocabulary-quiz-card"><p>根據提示寫出正確的{card.language === "ja" ? "日文" : "英文"}單字。</p><h2>{card.primaryTranslation || card.meanings[0]?.meaning || "請猜這個單字"}</h2><label>你的答案<input aria-label="你的答案" autoComplete="off" onChange={(event) => setAnswer(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && checked === null) submit(); }} placeholder="輸入答案" value={answer} /></label>{checked === null ? <><button className="button" disabled={!answer.trim()} onClick={submit} type="button">確認答案</button><button className="secondary-button compact" onClick={skip} type="button">不會，跳過這個單字</button></> : <><p className={`notice ${answerCorrect ? "success" : "error"}`} role="status">{answerCorrect ? "答對了！做得很好。" : <>{skipped ? "已跳過。" : "答錯了。"}正確答案是「{correctAnswer}」。</>}</p><button className="button" onClick={() => next(answerCorrect)} type="button">下一題</button></>}</div></section>;
}

function VocabularyCardRow({ card, onFavorite, onOpen, onToggle, selected, selectionMode }: { card: VocabularyCard; onFavorite: () => void; onOpen: () => void; onToggle: () => void; selected: boolean; selectionMode: boolean }) {
  const level = card.jlptLevel || card.cefrLevel;
  return <article className={`vocabulary-card ${selectionMode ? "selection-on" : ""}`}><label className="vocabulary-card-selection" hidden={!selectionMode}><input aria-label={`選取 ${card.word}`} checked={selected} onChange={onToggle} type="checkbox" /></label><button className="vocabulary-card-main" onClick={onOpen} type="button"><div><div className="vocabulary-word-meta"><span className="vocabulary-language-badge">{card.language === "ja" ? "日文" : card.language === "en" ? "英文" : card.language.toUpperCase()}</span>{level && <span className="vocabulary-level-badge">{level}</span>}</div><h3>{card.word}</h3><p>{card.reading || card.romaji || "未設定讀音"}</p></div><div><strong>{card.primaryTranslation || card.meanings.map((meaning) => meaning.meaning).join("、") || "尚未填寫意思"}</strong><p className="vocabulary-mastery-label">{masteryLabels[card.currentLevel] || masteryLabels[0]} · {card.totalAttempts} 次 · {Math.round(card.correctRate)}%</p>{card.tags.length > 0 && <div className="vocabulary-card-tags">{card.tags.slice(0, 3).map((tag) => <span key={tag.id}>{tag.name}</span>)}</div>}</div></button><div className="vocabulary-card-side"><button aria-label={card.isFavorite ? "取消收藏" : "加入收藏"} className={card.isFavorite ? "vocabulary-star active" : "vocabulary-star"} onClick={onFavorite} type="button">★</button></div></article>;
}

function LearningPanels({ className, data, recentCards, reviewed, streak, onOpenCard }: { className: string; data: VocabularyWorkspaceData; recentCards: VocabularyCard[]; reviewed: number; streak: number; onOpenCard: (card: VocabularyCard) => void }) {
  const progress = Math.min(100, data.settings.dailyReviewGoal ? reviewed / data.settings.dailyReviewGoal * 100 : 0);
  return <aside className={className}><section><h2>今日目標</h2><p>{reviewed}／{data.settings.dailyReviewGoal} 已複習</p><div className="vocabulary-progress-track"><i style={{ width: `${progress}%` }} /></div></section><section><h2>連續學習</h2><p>{streak ? `已連續 ${streak} 天複習` : "今天開始累積學習紀錄"}</p></section><section className="vocabulary-recent-list"><h2>最近學習</h2>{recentCards.length ? recentCards.map((card) => <button key={card.id} onClick={() => onOpenCard(card)} type="button">{card.word}</button>) : <p>加入單字後會顯示在這裡。</p>}</section></aside>;
}

function LegacyVocabularyWorkspace({ initialData }: { initialData?: VocabularyWorkspaceData }) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const [data, setData] = useState(initialData ?? emptyVocabulary); const [loaded, setLoaded] = useState(Boolean(initialData)); const [tab, setTab] = useState<Tab>("overview"); const [query, setQuery] = useState(""); const [language, setLanguage] = useState("all"); const [deckFilter, setDeckFilter] = useState<string | null>(null); const [pending, setPending] = useState(false); const [error, setError] = useState<string | null>(null); const [draft, setDraft] = useState<Draft | null>(null); const [selected, setSelected] = useState<VocabularyCard | null>(null); const [deleting, setDeleting] = useState<VocabularyCard | null>(null); const [chosen, setChosen] = useState(new Set<string>()); const [tagName, setTagName] = useState(""); const [deckName, setDeckName] = useState(""); const [quizAnswer, setQuizAnswer] = useState(""); const [quizMessage, setQuizMessage] = useState<string | null>(null);
  const trash = tab === "trash";
  useEffect(() => { const node = document.createElement("style"); node.dataset.vocabularyStyles = "true"; node.textContent = `${vocabularyCss}${vocabularyButtonCss}${vocabularySurfaceCss}${vocabularyTransparentCss}`; document.head.appendChild(node); return () => node.remove(); }, []);
  useEffect(() => {
    let active = true;
    const cached = readClientResource<VocabularyWorkspaceData>("vocabulary:standard");
    if (cached) { setData(cached); setLoaded(true); }
    const loadInitial = async () => {
      try {
        const response = await fetch("/api/vocabulary", { cache: "no-store" });
        if (!response.ok) throw new Error("單字資料暫時無法讀取。");
        const next = await response.json() as VocabularyWorkspaceData;
        if (!active) return;
        setData(next); setLoaded(true); writeClientResource("vocabulary:standard", next);
      } catch (cause) { if (active && !cached) setError(cause instanceof Error ? cause.message : "單字資料暫時無法讀取。"); }
    };
    void loadInitial();
    return () => { active = false; };
  }, []);
  useEffect(() => { if (loaded) writeClientResource("vocabulary:standard", data); }, [data, loaded]);
  useEffect(() => { if (searchParams.get("new") !== "1") return; setDraft((current) => current ?? blankDraft()); router.replace("/vocabulary", { scroll: false }); }, [router, searchParams]);
  const cards = useMemo(() => data.cards.filter((card) => { const text = `${card.word} ${card.reading || ""} ${card.primaryTranslation || ""} ${card.notes || ""} ${card.tags.map((tag) => tag.name).join(" ")}`.toLowerCase(); return (language === "all" || card.language === language) && text.includes(query.trim().toLowerCase()) && (tab !== "favorites" || card.isFavorite) && (!deckFilter || card.deckIds.includes(deckFilter)); }), [data.cards, deckFilter, language, query, tab]);
  const dueCards = useMemo(() => data.cards.filter((card) => card.learningStatus !== "paused" && card.nextReviewAt && new Date(card.nextReviewAt).getTime() <= Date.now()), [data.cards]);
  const stat = useMemo(() => ({ total: data.cards.length, ja: data.cards.filter((card) => card.language === "ja").length, en: data.cards.filter((card) => card.language === "en").length, mastered: data.cards.filter((card) => card.masteryLevel >= 5).length, learning: data.cards.filter((card) => card.learningStatus === "learning" || card.learningStatus === "reviewing").length, reviewed: data.reviewLogs.filter((log) => day(log.reviewedAt) === day(new Date().toISOString())).length, correct: data.reviewLogs.filter((log) => day(log.reviewedAt) === day(new Date().toISOString()) && log.answerResult).length }), [data]);
  async function load(withTrash = trash) { const response = await fetch(`/api/vocabulary${withTrash ? "?trash=1" : ""}`, { cache: "no-store" }); if (!response.ok) throw new Error("單字資料暫時無法讀取。"); const next = await response.json() as VocabularyWorkspaceData; setData(next); setLoaded(true); if (!withTrash) writeClientResource("vocabulary:standard", next); }
  async function request(url: string, init: RequestInit) { setPending(true); setError(null); try { const response = await fetch(url, { ...init, headers: { "Content-Type": "application/json", ...(init.headers || {}) } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || "操作失敗"); return body; } catch (cause) { setError(cause instanceof Error ? cause.message : "操作失敗，請稍後再試。"); return null; } finally { setPending(false); } }
  async function save(event: FormEvent) { event.preventDefault(); if (!draft) return; let languageDetails: Record<string, unknown> = {}; try { languageDetails = JSON.parse(draft.languageDetails || "{}"); } catch { setError("語言補充資料必須是有效的 JSON。\n例如：{\"verbType\":\"五段動詞\"}"); return; } const meanings = draft.meaningsText.split("\n").map((value) => value.trim()).filter(Boolean).map((meaning, index) => ({ meaning, language: "zh-TW", isPrimary: index === 0, sortOrder: index })); const examples = draft.examplesText.split("\n").map((value) => value.trim()).filter(Boolean).map((value) => { const [sentence, translation] = value.split("｜"); return { sentence: sentence.trim(), translation: translation?.trim() || null }; }); const result = await request("/api/vocabulary", { method: draft.id ? "PUT" : "POST", body: JSON.stringify({ ...draft, jlptLevel: draft.jlptLevel || null, cefrLevel: draft.cefrLevel || null, languageDetails, meanings, examples }) }); if (result) { setDraft(null); await load(false); } }
  async function mutate(ids: string[], action: "trash" | "restore" | "permanent") { const result = await request("/api/vocabulary", { method: "PATCH", body: JSON.stringify({ ids, action }) }); if (result) { setSelected(null); setDeleting(null); setChosen(new Set()); await load(action === "restore" ? false : trash); } }
  async function review(card: VocabularyCard, rating: ReviewRating) { const result = await request("/api/vocabulary/review", { method: "POST", body: JSON.stringify({ cardId: card.id, rating }) }); if (result) await load(false); }
  async function createTaxonomy(type: "tag" | "deck") { const name = type === "tag" ? tagName : deckName; if (!name.trim()) return; const result = await request("/api/vocabulary/taxonomy", { method: "POST", body: JSON.stringify(type === "tag" ? { type, name, color: "#2f67c7" } : { type, name }) }); if (result) { if (type === "tag") setTagName(""); else setDeckName(""); await load(false); } }
  async function saveSettings(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const result = await request("/api/vocabulary/taxonomy", { method: "POST", body: JSON.stringify({ type: "settings", dailyNewGoal: Number(form.get("dailyNewGoal")), dailyReviewGoal: Number(form.get("dailyReviewGoal")), flashcardPreferences: data.settings.flashcardPreferences }) }); if (result) await load(false); }
  function setField(key: keyof Draft, value: Draft[keyof Draft]) { setDraft((current) => current ? { ...current, [key]: value } : current); }
  const toggleChoice = (id: string) => setChosen((current) => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; });
  const allChosen = cards.length > 0 && cards.every((card) => chosen.has(card.id));
  const selectCard = chosen.size ? cards.find((card) => chosen.has(card.id)) || null : deleting;
  return <section className="vocabulary-workspace">{pending && <OperationStatus label="正在更新單字資料…" />}{error && <p className="notice error" role="alert">{error}</p>}<header className="vocabulary-header"><div><p className="eyebrow">VOCABULARY LEARNING</p><h1>單字學習</h1><p>記錄、整理與間隔複習你的日文、英文及更多語言。</p></div><button className="button vocabulary-primary-action" onClick={() => setDraft(blankDraft())} type="button">＋ 新增單字</button></header><nav aria-label="單字學習功能" className="vocabulary-tabs">{tabs.map((item) => <button className={tab === item.id ? "active" : ""} key={item.id} onClick={() => { setTab(item.id); setChosen(new Set()); setQuery(""); setDeckFilter(null); }} type="button">{item.label}{item.id === "review" && dueCards.length > 0 ? <b>{dueCards.length}</b> : null}</button>)}</nav>
    {tab === "lookup" && <VocabularyLookupPanel cards={data.cards} mode="lookup" onAdd={(entry) => setDraft({ ...blankDraft(), ...entry })} />}
    {tab === "assistant" && <VocabularyLookupPanel cards={data.cards} mode="assistant" onAdd={(entry) => setDraft({ ...blankDraft(), ...entry })} />}
    {tab === "review" && <FlashcardReview cards={dueCards} direction="native" onComplete={async (reviews) => { for (const item of reviews) { const card = dueCards.find((candidate) => candidate.id === item.cardId); if (card) await review(card, item.answerResult ? "good" : "again"); } }} pending={pending} />}
    {tab === "decks" && <section className="vocabulary-taxonomy"><div><p className="eyebrow">WORD BOOKS</p><h2>單字本</h2><form onSubmit={(event) => { event.preventDefault(); void createTaxonomy("deck"); }}><input onChange={(event) => setDeckName(event.target.value)} placeholder="例如：JLPT N3、程式英文" value={deckName} /><button className="button" type="submit">新增單字本</button></form><div className="vocabulary-chip-list">{data.decks.map((deck) => <button key={deck.id} onClick={() => { setDeckFilter(deck.id); setTab("overview"); }} type="button"><strong>{deck.name}</strong><span>{deck.cardIds.length} 個單字</span></button>)}{!data.decks.length && <p>還沒有單字本。</p>}</div></div><div><p className="eyebrow">TAGS</p><h2>標籤</h2><form onSubmit={(event) => { event.preventDefault(); void createTaxonomy("tag"); }}><input onChange={(event) => setTagName(event.target.value)} placeholder="例如：動漫、TOEIC" value={tagName} /><button className="button" type="submit">新增標籤</button></form><div className="vocabulary-tag-list">{data.tags.map((tag) => <span key={tag.id} style={{ borderColor: tag.color || undefined }}>{tag.name}</span>)}{!data.tags.length && <p>還沒有標籤。</p>}</div></div></section>}
    {tab === "stats" && <section className="vocabulary-stats"><div className="vocabulary-stat-grid">{[["總單字", stat.total], ["日文", stat.ja], ["英文", stat.en], ["今日複習", stat.reviewed], ["今日答對", stat.correct], ["已掌握", stat.mastered]].map(([label, value]) => <div key={String(label)}><strong>{value}</strong><span>{label}</span></div>)}</div><section className="vocabulary-chart"><h2>熟練度分布</h2>{[0, 1, 2, 3, 4, 5].map((level) => { const count = data.cards.filter((card) => card.masteryLevel === level).length; return <div key={level}><span>{level}／5</span><i style={{ width: `${stat.total ? (count / stat.total) * 100 : 0}%` }} /><b>{count}</b></div>; })}</section></section>}
    {tab === "transfer" && <Transfer request={request} load={load} />}
    {tab === "settings" && <form className="vocabulary-settings" onSubmit={saveSettings}><h2>學習設定</h2><label>每日新增目標<input defaultValue={data.settings.dailyNewGoal} min="0" name="dailyNewGoal" type="number" /></label><label>每日複習目標<input defaultValue={data.settings.dailyReviewGoal} min="1" name="dailyReviewGoal" type="number" /></label><button className="button" disabled={pending} type="submit">儲存設定</button></form>}
    {tab === "quiz" && <section className="vocabulary-quiz">{cards[0] ? <><p className="eyebrow">QUICK QUIZ</p><h2>{cards[0].primaryTranslation || cards[0].meanings[0]?.meaning || "請猜這個單字"}</h2><p>請輸入對應的{cards[0].language === "ja" ? "日文" : "英文"}單字。</p><input onChange={(event) => setQuizAnswer(event.target.value)} placeholder="輸入答案" value={quizAnswer} /><button className="button" onClick={() => setQuizMessage(quizAnswer.trim().toLocaleLowerCase() === cards[0].word.toLocaleLowerCase() ? "答對了！" : `再試一次，答案是「${cards[0].word}」。`)} type="button">確認答案</button>{quizMessage && <p className="notice">{quizMessage}</p>}</> : <p>新增單字後即可開始測驗。</p>}</section>}
	    {["overview", "favorites", "trash"].includes(tab) && <><div className="vocabulary-summary"><button onClick={() => setTab("review")} type="button"><strong>{dueCards.length}</strong><span>今日待複習</span></button><div><strong>{stat.learning}</strong><span>學習中</span></div><div><strong>{stat.mastered}</strong><span>已掌握</span></div></div><div className="vocabulary-filters"><input aria-label="搜尋單字" onChange={(event) => setQuery(event.target.value)} placeholder="搜尋單字、讀音、意思或標籤" value={query} /><select aria-label="篩選語言" onChange={(event) => setLanguage(event.target.value)} value={language}><option value="all">所有語言</option><option value="ja">日文</option><option value="en">英文</option></select><button className="secondary-button compact" onClick={() => setChosen(allChosen ? new Set() : new Set(cards.map((card) => card.id)))} type="button">{allChosen ? "取消全選" : "全選"}</button>{chosen.size > 0 && <button className="delete-button compact" onClick={() => setDeleting(selectCard)} type="button">{trash ? "永久刪除" : "移至垃圾桶"}</button>}</div><div className="vocabulary-card-list">{!loaded ? <VocabularyListSkeleton /> : <>{cards.map((card) => <article className="vocabulary-card" key={card.id}><label><input aria-label={`選取 ${card.word}`} checked={chosen.has(card.id)} onChange={() => toggleChoice(card.id)} type="checkbox" /></label><button className="vocabulary-card-main" onClick={() => setSelected(card)} type="button"><div><small>{card.language.toUpperCase()} · {card.partOfSpeech || "未分類"}</small><h3>{card.word}</h3><p>{card.reading || card.romaji || ""}</p></div><div><strong>{card.primaryTranslation || card.meanings.map((meaning) => meaning.meaning).join("、") || "尚未填寫意思"}</strong><p>{"★".repeat(card.masteryLevel)}{"☆".repeat(5 - card.masteryLevel)}</p></div></button><button aria-label={card.isFavorite ? "取消收藏" : "加入收藏"} className={card.isFavorite ? "vocabulary-star active" : "vocabulary-star"} onClick={() => { const payload = { ...fromCard(card), isFavorite: !card.isFavorite, meanings: card.meanings, examples: card.examples, languageDetails: card.languageDetails }; void request("/api/vocabulary", { method: "PUT", body: JSON.stringify(payload) }).then((result) => result && load(false)); }} type="button">★</button></article>)}{!cards.length && <div className="vocabulary-empty"><strong>{trash ? "垃圾桶是空的" : "尚未建立單字"}</strong><p>{trash ? "被刪除的單字會保留在此處，可於之後還原。" : "從右上角新增第一筆單字，開始建立你的單字庫。"}</p></div>}</>}</div></>}
    <ModalDialog onClose={() => setDraft(null)} open={Boolean(draft)} pending={pending} title={draft?.id ? "修改單字" : "新增單字"}>{draft && <Editor data={data} draft={draft} pending={pending} setField={setField} onCancel={() => setDraft(null)} onSave={save} />}</ModalDialog><ModalDialog onClose={() => setSelected(null)} open={Boolean(selected)} pending={pending} title={selected?.word || "單字詳細資料"}>{selected && <div className="vocabulary-detail"><p className="eyebrow">{selected.language.toUpperCase()} · {selected.learningStatus}</p><h2>{selected.word}</h2><p>{selected.reading || selected.romaji}</p><h3>{selected.primaryTranslation || selected.meanings.map((meaning) => meaning.meaning).join("、")}</h3>{selected.meanings.length > 0 && <section><h4>意思</h4>{selected.meanings.map((meaning) => <p key={meaning.id}>{meaning.meaning}{meaning.partOfSpeech ? ` · ${meaning.partOfSpeech}` : ""}</p>)}</section>}{selected.examples.length > 0 && <section><h4>例句</h4>{selected.examples.map((example) => <p key={example.id}><strong>{example.sentence}</strong><br />{example.translation}</p>)}</section>}<p>{selected.notes}</p><div className="dialog-actions">{selected.deletedAt ? <><button className="button" onClick={() => void mutate([selected.id], "restore")} type="button">還原</button><button className="delete-button" onClick={() => setDeleting(selected)} type="button">永久刪除</button></> : <><button className="secondary-button" onClick={() => { setDraft(fromCard(selected)); setSelected(null); }} type="button">修改</button><button className="delete-button" onClick={() => setDeleting(selected)} type="button">移至垃圾桶</button></>}</div></div>}</ModalDialog><ConfirmDialog confirmLabel={trash || deleting?.deletedAt ? "永久刪除" : "移至垃圾桶"} description={trash || deleting?.deletedAt ? `確定要永久刪除「${deleting?.word || ""}」嗎？此操作無法復原。` : `確定要將「${deleting?.word || ""}」移至垃圾桶嗎？`} onCancel={() => setDeleting(null)} onConfirm={() => void mutate(chosen.size ? [...chosen] : deleting ? [deleting.id] : [], trash || deleting?.deletedAt ? "permanent" : "trash")} open={Boolean(deleting)} pending={pending} title={trash || deleting?.deletedAt ? "永久刪除單字？" : "移至垃圾桶？"} />
  </section>;
}

function VocabularyListSkeleton() {
  return <div aria-busy="true" aria-label="正在載入單字" className="vocabulary-card-list">{Array.from({ length: 5 }, (_, index) => <div className="vocabulary-card vocabulary-card-skeleton" key={index}><span className="skeleton-block skeleton-checkbox" /><div className="vocabulary-card-main"><div><span className="skeleton-block skeleton-line short" /><span className="skeleton-block skeleton-line medium" /></div><div><span className="skeleton-block skeleton-line" /><span className="skeleton-block skeleton-line short" /></div></div></div>)}</div>;
}

function Editor({ data, draft, pending, setField, onCancel, onSave }: { data: VocabularyWorkspaceData; draft: Draft; pending: boolean; setField: (key: keyof Draft, value: Draft[keyof Draft]) => void; onCancel: () => void; onSave: (event: FormEvent) => void }) {
  const [aiPending, setAiPending] = useState(false); const [aiHint, setAiHint] = useState<string | null>(null);
  async function autoFill() {
    if (!draft.word.trim()) { setAiHint("請先輸入單字，再取得 AI 建議。"); return; }
    setAiPending(true); setAiHint(null);
    try {
      const response = await fetch("/api/vocabulary/assistant", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "autocomplete", language: draft.language === "ja" || draft.language === "en" ? draft.language : "auto", prompt: `請補全單字卡：${draft.word}` }) });
      const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || "AI 補全暫時無法使用。");
      const suggestion = body.suggestedCard as Record<string, unknown> | undefined;
      if (!suggestion) { setAiHint("AI 未提供可採用欄位，請保留手動編輯。 "); return; }
      const text = (key: string) => typeof suggestion[key] === "string" ? suggestion[key] : "";
      (["reading", "romaji", "primaryTranslation", "englishDefinition", "partOfSpeech", "jlptLevel", "cefrLevel"] as const).forEach((key) => { const value = text(key); if (value && value !== "未確認") setField(key, value); });
      if (Array.isArray(suggestion.meanings)) setField("meaningsText", suggestion.meanings.filter((value): value is string => typeof value === "string").join("\n"));
      if (Array.isArray(suggestion.examples)) setField("examplesText", suggestion.examples.map((item) => item && typeof item === "object" ? `${String((item as { sentence?: unknown }).sentence || "")}${(item as { translation?: unknown }).translation ? `｜${String((item as { translation: unknown }).translation)}` : ""}` : "").filter(Boolean).join("\n"));
      setAiHint("已套用 AI 建議；請先核對內容，再自行儲存。 ");
    } catch (cause) { setAiHint(cause instanceof Error ? cause.message : "AI 補全暫時無法使用。"); } finally { setAiPending(false); }
  }
  const japanese = draft.language === "ja";
  return <form className="vocabulary-form" onSubmit={onSave}><div className="vocabulary-form-grid"><label>語言<select value={draft.language} onChange={(event) => setField("language", event.target.value)}><option value="ja">日文</option><option value="en">英文</option></select></label><label>單字<input autoFocus required value={draft.word} onChange={(event) => setField("word", event.target.value)} /></label>{japanese && <label>讀音／假名<input value={draft.reading} onChange={(event) => setField("reading", event.target.value)} /></label>}<label>主要意思<input value={draft.primaryTranslation} onChange={(event) => setField("primaryTranslation", event.target.value)} /></label><label>詞性<input placeholder={japanese ? "動詞、名詞、形容詞…" : "noun、verb、adjective…"} value={draft.partOfSpeech} onChange={(event) => setField("partOfSpeech", event.target.value)} /></label>{japanese && <label>JLPT 等級<select value={draft.jlptLevel} onChange={(event) => setField("jlptLevel", event.target.value)}><option value="">未設定</option>{["N5", "N4", "N3", "N2", "N1"].map((value) => <option key={value}>{value}</option>)}</select></label>}</div><div className="vocabulary-ai-autofill"><button className="secondary-button compact" disabled={aiPending || pending || !draft.word.trim()} onClick={() => void autoFill()} type="button">{aiPending ? "AI 補全中…" : "✨ AI 自動補全"}</button><small>AI 建議不會自動儲存；請先核對後再自行儲存。</small>{aiHint && <p className="notice">{aiHint}</p>}</div><label>多個意思（每行一個）<textarea placeholder={japanese ? "給予\n賦予" : "maintain\nkeep"} rows={3} value={draft.meaningsText} onChange={(event) => setField("meaningsText", event.target.value)} /></label><label>{japanese ? "例句（每行一個；可用｜接繁中翻譯）" : "例句（每行一個；可用｜接中文翻譯）"}<textarea placeholder={japanese ? "先生は学生にチャンスを与えた。｜老師給了學生機會。" : "I maintain this project.｜我維護這個專案。"} rows={3} value={draft.examplesText} onChange={(event) => setField("examplesText", event.target.value)} /></label><div className="vocabulary-form-grid"><label>標籤<select multiple value={draft.tagIds} onChange={(event) => setField("tagIds", Array.from(event.target.selectedOptions).map((option) => option.value))}>{data.tags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name}</option>)}</select><small>按住 Ctrl／⌘ 可複選</small></label><label>單字本<select multiple value={draft.deckIds} onChange={(event) => setField("deckIds", Array.from(event.target.selectedOptions).map((option) => option.value))}>{data.decks.map((deck) => <option key={deck.id} value={deck.id}>{deck.name}</option>)}</select><small>同一單字可放入多本</small></label></div><label>備註<textarea rows={3} value={draft.notes} onChange={(event) => setField("notes", event.target.value)} /></label><label className="vocabulary-favorite"><input checked={draft.isFavorite} onChange={(event) => setField("isFavorite", event.target.checked)} type="checkbox" /> 加入收藏</label><div className="dialog-actions"><button className="button" disabled={pending} type="submit">{pending ? "儲存中…" : draft.id ? "儲存修改" : "新增單字"}</button><button className="secondary-button" disabled={pending} onClick={onCancel} type="button">取消</button></div></form>;
}
function Transfer({ request, load }: { request: (url: string, init: RequestInit) => Promise<Record<string, unknown> | null>; load: (trash?: boolean) => Promise<void> }) { const [text, setText] = useState(""); const rows = text.split("\n").map((line) => line.split(",").map((value) => value.trim())).filter((row) => row[0]); return <section className="vocabulary-transfer"><div><h2>匯出備份</h2><p>CSV 可用試算表開啟；JSON 包含單字、標籤、單字本與複習紀錄。</p><div className="dialog-actions vocabulary-export-actions"><a className="button" href="/api/vocabulary/export">下載 CSV</a><a className="secondary-button" href="/api/vocabulary/export?format=json">下載 JSON 備份</a></div></div><div><h2>批次新增</h2><p>貼上「單字,讀音,意思」，每行一筆；建立後可再補齊完整資料。</p><textarea aria-label="批次新增單字" onChange={(event) => setText(event.target.value)} placeholder="与える,あたえる,給予\nmaintain,,維持" rows={7} value={text} /><button className="button" disabled={!rows.length} onClick={async () => { for (const [word, reading, meaning] of rows) { const result = await request("/api/vocabulary", { method: "POST", body: JSON.stringify({ ...blankDraft(), word, reading, primaryTranslation: meaning, language: /[\u3040-\u30ff\u3400-\u9fff]/.test(word) ? "ja" : "en" }) }); if (!result) return; } setText(""); await load(false); }} type="button">建立 {rows.length} 筆單字</button></div></section>; }
